```go
type node struct {
	key, val   int
	prev, next *node
}

type LRUCache struct {
	cap        int
	items      map[int]*node
	head, tail *node // head = most recent, tail = least recent
}

func Constructor(capacity int) LRUCache {
	head := &node{}
	tail := &node{}
	head.next = tail
	tail.prev = head
	return LRUCache{
		cap:   capacity,
		items: make(map[int]*node, capacity),
		head:  head,
		tail:  tail,
	}
}

func (c *LRUCache) Get(key int) int {
	n, ok := c.items[key]
	if !ok {
		return -1
	}
	c.moveToFront(n)
	return n.val
}

func (c *LRUCache) Put(key int, value int) {
	if n, ok := c.items[key]; ok {
		n.val = value
		c.moveToFront(n)
		return
	}
	n := &node{key: key, val: value}
	c.items[key] = n
	c.addToFront(n)
	if len(c.items) > c.cap {
		lru := c.tail.prev
		c.remove(lru)
		delete(c.items, lru.key)
	}
}

func (c *LRUCache) addToFront(n *node) {
	n.prev = c.head
	n.next = c.head.next
	c.head.next.prev = n
	c.head.next = n
}

func (c *LRUCache) remove(n *node) {
	n.prev.next = n.next
	n.next.prev = n.prev
}

func (c *LRUCache) moveToFront(n *node) {
	c.remove(n)
	c.addToFront(n)
}
```

A map gives O(1) lookup to the node, and a hand-rolled doubly linked list keeps recency order, so every get and put is a constant number of pointer swaps. Sentinel head and tail nodes remove the nil checks at the ends.

Time: O(1) per Get and Put. Space: O(capacity).

