def first_unique_char(s: str) -> str:
    counts = {}
    for ch in s:
        counts[ch] = counts.get(ch, 0) + 1
    for ch in s:
        if counts[ch] == 1:
            return ch
    return ""
```

Two passes: the first counts every character, the second returns the first one whose count is 1, or an empty string if none exists. Time is O(n) and space is O(k), where k is the number of distinct characters.

Sure. Here's the simpler version.

Keep a map from key to node, and a doubly linked list where the front is most recently used and the back is least recently used. Get looks up the map, moves that node to the front, and returns its value. Put updates or inserts, moves it to the front, and if we're over capacity, drops the node at the back and deletes it from the map. Both are O(1) because the map finds the node and the list moves it with just pointer swaps.

```go
type node struct {
	key, val   int
	prev, next *node
}

type LRUCache struct {
	cap        int
	items      map[int]*node
	head, tail *node
}

func Constructor(capacity int) LRUCache {
	head, tail := &node{}, &node{}
	head.next, tail.prev = tail, head
	return LRUCache{cap: capacity, items: map[int]*node{}, head: head, tail: tail}
}

func (c *LRUCache) Get(key int) int {
	n, ok := c.items[key]
	if !ok {
		return -1
	}
	c.moveFront(n)
	return n.val
}

func (c *LRUCache) Put(key, value int) {
	if n, ok := c.items[key]; ok {
		n.val = value
		c.moveFront(n)
		return
	}
	n := &node{key: key, val: value}
	c.items[key] = n
	c.addFront(n)
	if len(c.items) > c.cap {
		lru := c.tail.prev
		c.remove(lru)
		delete(c.items, lru.key)
	}
}

func (c *LRUCache) addFront(n *node) {
	n.prev, n.next = c.head, c.head.next
	c.head.next.prev = n
	c.head.next = n
}

func (c *LRUCache) remove(n *node) {
	n.prev.next = n.next
	n.next.prev = n.prev
}

func (c *LRUCache) moveFront(n *node) {
	c.remove(n)
	c.addFront(n)
}
```

